### Part 1: Project Setup

We will create a root folder containing both the backend and the frontend.

1.  Create a folder named `fullstack-app`.
2.  Open your terminal in this folder.

### Part 2: Backend (Node & Express)

1.  Create a folder named `server`.
2.  Initialize the project:
    ```bash
    cd server
    npm init -y
    npm install express cors nodemon
    ```
3.  Create a file named `index.js` inside `server`.

**`server/index.js`**
```javascript
const express = require('express');
const cors = require('cors');

const app = express();
const PORT = 5000;

// Middleware
app.use(cors()); // Allows React to talk to Express
app.use(express.json()); // Parses JSON bodies

// Dummy Data (In-memory database)
let items = [
    { id: 1, name: "React", type: "Frontend" },
    { id: 2, name: "Express",master: "Backend" }
];

// Route 1: Get all items
app.get('/api/items', (req, res) => {
    res.json(items);
});

// Route 2: Add a new item
app.post('/api/items', (req, res) => {
    const newItem = {
        id: items.length + 1,
        name: req.body.name,
        type: req.body.type
    };
    items.push(newItem);
    res.status(201).json(newItem);
});

// Start Server
app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

